73	
74	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
75	    @Override
76	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
77	        Collection<Owner> owners;
78	        if (lastName != null) {
79	            owners = this.clinicService.findOwnerByLastName(lastName);
80	        } else {
81	            owners = this.clinicService.findAllOwners();
82	        }
83	        if (owners.isEmpty()) {
84	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
85	        }
86	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
87	    }
88	
89	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
90	    @Override
91	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
92	        Owner owner = this.clinicService.findOwnerById(ownerId);
93	        if (owner == null) {
94	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
95	        }
96	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
97	    }
98	
99	    /** Matches a syntactically valid email address: a local part and domain (with at least one dot)
100	     *  separated by '@', none of which contain whitespace or a second '@'. */
101	    private static final java.util.regex.Pattern EMAIL_PATTERN =
102	        java.util.regex.Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
103	
104	    /**
105	     * Normalize the optional email: absent stays absent; when present it must be syntactically
106	     * valid and is lower-cased. Returns {@code false} if present but invalid.
107	     */
108	    private boolean normalizeEmail(Owner owner) {
109	        String email = owner.getEmail();
110	        if (email == null || email.isEmpty()) {
111	            owner.setEmail(null);
112	            return true;
113	        }
114	        if (!EMAIL_PATTERN.matcher(email).matches()) {
115	            return false;
116	        }
117	        owner.setEmail(email.toLowerCase(java.util.Locale.ROOT));
118	        return true;
119	    }
120	
121	    /**
122	     * Normalize a telephone number to E.164 form: strip spaces, dashes and brackets; keep a leading
123	     * '+' and country code when present, otherwise assume country code '+61' and drop a single leading
124	     * '0' from the national digits. The result must have 8 to 15 digits after the '+'.
125	     *
126	     * @return the E.164 string (e.g. {@code +61412345678}), or {@code null} when the input cannot form
127	     *         a valid E.164 number.
128	     */
129	    private static String toE164(String raw) {
130	        if (raw == null) {
131	            return null;
132	        }
133	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
134	        String digits;
135	        if (cleaned.startsWith("+")) {
136	            digits = cleaned.substring(1);
137	        } else {
138	            if (cleaned.startsWith("0")) {
139	                cleaned = cleaned.substring(1);
140	            }
141	            digits = "61" + cleaned;
142	        }
143	        if (!digits.matches("\\d{8,15}")) {
144	            return null;
145	        }
146	        return "+" + digits;
147	    }
148	
149	    /**
150	     * Build the customer code {@code <LAST3>-<NNNN>}: LAST3 is the upper-cased first three letters of
151	     * the last name and NNNN is a global 4-digit zero-padded sequence equal to one more than the
152	     * current number of owners (e.g. {@code SMI-0007}).
153	     */
154	    private String nextCustomerCode(String lastName) {
155	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(java.util.Locale.ROOT);
156	        int sequence = this.clinicService.findAllOwners().size() + 1;
157	        return String.format("%s-%04d", last3, sequence);
158	    }
159	
160	    /** Common street-type abbreviations expanded during address normalization. */
161	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS =
162	        java.util.Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
163	
164	    /**
165	     * Normalize an address: {@code null} becomes empty, surrounding whitespace is trimmed, internal
166	     * runs of whitespace are collapsed to a single space, the value is upper-cased and common
167	     * street-type abbreviations (ST-&gt;STREET, RD-&gt;ROAD, AVE-&gt;AVENUE) are expanded token by token.
168	     */
169	    private static String normalizeAddress(String value) {
170	        if (value == null) {
171	            return "";
172	        }
173	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
174	        if (collapsed.isEmpty()) {
175	            return "";
176	        }
177	        String[] tokens = collapsed.split(" ");
178	        StringBuilder sb = new StringBuilder(collapsed.length());
179	        for (int i = 0; i < tokens.length; i++) {
180	            if (i > 0) {
181	                sb.append(' ');
182	            }
183	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
184	        }
185	        return sb.toString();
186	    }
187	
188	    /**
189	     * Normalize a value for household-duplicate comparison: {@code null} becomes empty, surrounding
190	     * whitespace is trimmed, internal runs of whitespace are collapsed to a single space and the result
191	     * is lower-cased, so the comparison is case-insensitive with collapsed whitespace.
192	     */
193	    private static String normalizeForHousehold(String value) {
194	        if (value == null) {
195	            return "";
196	        }
197	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
198	    }
199	
200	    /**
201	     * Return the owners that already share this owner's household, i.e. have the same last name and
202	     * address compared case-insensitively with collapsed whitespace.
203	     */
204	    private List<Owner> householdMembers(Owner owner) {
205	        String lastName = normalizeForHousehold(owner.getLastName());
206	        String address = normalizeForHousehold(owner.getAddress());
207	        List<Owner> members = new java.util.ArrayList<>();
208	        for (Owner existing : this.clinicService.findAllOwners()) {
209	            if (normalizeForHousehold(existing.getLastName()).equals(lastName)
210	                && normalizeForHousehold(existing.getAddress()).equals(address)) {
211	                members.add(existing);
212	            }
213	        }
214	        return members;
215	    }
216	
217	    /**
218	     * Return {@code true} when another owner already shares this owner's household, i.e. has the same
219	     * last name and address compared case-insensitively with collapsed whitespace.
220	     */
221	    private boolean sharesHouseholdWithExisting(Owner owner) {
222	        return !householdMembers(owner).isEmpty();
223	    }
224	
225	    /**
226	     * A stable, shared household identifier derived from the normalized last name and address, so every
227	     * owner in the same household deterministically resolves to the same value.
228	     */
229	    private static String householdIdFor(Owner owner) {
230	        String key = normalizeForHousehold(owner.getLastName()) + "|" + normalizeForHousehold(owner.getAddress());
231	        try {
232	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
233	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
234	            StringBuilder sb = new StringBuilder(24);
235	            for (int i = 0; i < 12; i++) {
236	                sb.append(String.format("%02X", digest[i]));
237	            }
238	            return sb.toString();
239	        }
240	        catch (java.security.NoSuchAlgorithmException e) {
241	            throw new IllegalStateException(e);
242	        }
243	    }
244	
245	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
246	    @Override
247	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
248	        HttpHeaders headers = new HttpHeaders();
249	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
250	        String telephone = toE164(owner.getTelephone());
251	        if (telephone == null) {
252	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
253	        }
254	        if (!normalizeEmail(owner)) {
255	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
256	        }
257	        String address = normalizeAddress(owner.getAddress());
258	        if (address.isEmpty()) {
259	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
260	        }
261	        owner.setAddress(address);
262	        for (Owner existing : this.clinicService.findAllOwners()) {
263	            String existingTelephone = toE164(existing.getTelephone());
264	            if (telephone.equals(existingTelephone)) {
265	                return new ResponseEntity<>(HttpStatus.CONFLICT);
266	            }
267	        }
268	        List<Owner> householdMembers = householdMembers(owner);
269	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
270	        if (!sharesHousehold && !householdMembers.isEmpty()) {
271	            return new ResponseEntity<>(HttpStatus.CONFLICT);
272	        }
273	        if (sharesHousehold && !householdMembers.isEmpty()) {
274	            String householdId = householdMembers.stream()
275	                .map(Owner::getHouseholdId)
276	                .filter(id -> id != null && !id.isBlank())
277	                .findFirst()
278	                .orElseGet(() -> householdIdFor(owner));
279	            owner.setHouseholdId(householdId);
280	            for (Owner member : householdMembers) {
281	                if (member.getHouseholdId() == null || member.getHouseholdId().isBlank()) {
282	                    member.setHouseholdId(householdId);
283	                    this.clinicService.saveOwner(member);
284	                }
285	            }
286	        }
287	        owner.setTelephone(telephone);
288	        if (owner.getRegistrationDate() == null) {
289	            owner.setRegistrationDate(java.time.LocalDate.now());
290	        }
291	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
292	        this.clinicService.saveOwner(owner);
293	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
294	        headers.setLocation(UriComponentsBuilder.newInstance()
295	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
296	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
297	    }
298	
299	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
300	    @Override
301	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
302	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
303	        if (currentOwner == null) {
304	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
305	        }
306	        currentOwner.setAddress(ownerFieldsDto.getAddress());
307	        currentOwner.setCity(ownerFieldsDto.getCity());
308	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
309	        currentOwner.setLastName(ownerFieldsDto.getLastName());
310	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
311	        currentOwner.setEmail(ownerFieldsDto.getEmail());
312	        if (!normalizeEmail(currentOwner)) {
313	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
314	        }
315	        this.clinicService.saveOwner(currentOwner);
316	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
317	    }
318	
319	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
320	    @Transactional
321	    @Override
322	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
323	        Owner owner = this.clinicService.findOwnerById(ownerId);
324	        if (owner == null) {
325	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
326	        }
327	        this.clinicService.deleteOwner(owner);
328	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
329	    }
330	
331	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
332	    @Override
333	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
334	        Owner owner = this.clinicService.findOwnerById(ownerId);
335	        if (owner == null) {
336	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
337	        }
338	        HttpHeaders headers = new HttpHeaders();
339	        Pet pet = petMapper.toPet(petFieldsDto);
340	        owner.setId(ownerId);
341	        pet.setOwner(owner);
342	        pet.getType().setName(null);
343	        this.clinicService.savePet(pet);
344	        PetDto petDto = petMapper.toPetDto(pet);
345	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
346	            .buildAndExpand(pet.getId()).toUri());
347	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
348	    }
349	
350	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
351	    @Override
352	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
353	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
354	        if (currentOwner != null) {
355	            Pet currentPet = this.clinicService.findPetById(petId);
356	            if (currentPet != null) {
357	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
358	                currentPet.setName(petFieldsDto.getName());
359	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
360	                this.clinicService.savePet(currentPet);
361	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
362	            }
363	        }
364	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
365	    }
366	
367	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
368	    @Override
369	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
370	        HttpHeaders headers = new HttpHeaders();
371	        Visit visit = visitMapper.toVisit(visitFieldsDto);
372	        Pet pet = new Pet();
373	        pet.setId(petId);
374	        visit.setPet(pet);
375	        this.clinicService.saveVisit(visit);
376	        VisitDto visitDto = visitMapper.toVisitDto(visit);
377	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
378	            .buildAndExpand(visit.getId()).toUri());
379	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
380	    }
381	
382	
383	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
384	    @Override
385	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
386	        Owner owner = this.clinicService.findOwnerById(ownerId);
387	        if (owner != null) {
388	            Pet pet = owner.getPet(petId);
389	            if (pet != null) {
390	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
391	            }
392	        }
393	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
394	    }
395	}
